#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <int TILE, int CIN, int COUT, int K, int REG>
__global__ void __launch_bounds__((TILE / REG) * (TILE / REG), 4) conv2d_cute_kernel(
    const cute::bfloat16_t* __restrict__ X,
    const cute::bfloat16_t* __restrict__ W,
    cute::bfloat16_t* __restrict__ Y,
    int N, int H, int Win,
    int Hout, int Wout)
{
    constexpr int SH = TILE + K - 1;
    constexpr int SW = TILE + K - 1;
    constexpr int BDIM = TILE / REG;
    const int n   = blockIdx.z;
    const int oh0 = blockIdx.y * TILE;
    const int ow0 = blockIdx.x * TILE;
    const int tx = threadIdx.x; // 0..BDIM-1
    const int ty = threadIdx.y; // 0..BDIM-1
    const int oh_base = oh0 + ty * REG;
    const int ow_base = ow0 + tx * REG;
    // Global input tensor for this batch element: (Cin, H, Win)
    const int64_t sXn = (int64_t)CIN * H * Win;
    const int64_t sXc = (int64_t)H * Win;
    auto mX = make_tensor(
        make_gmem_ptr(X + (int64_t)n * sXn),
        make_shape(CIN, H, Win),
        make_stride(sXc, (int64_t)Win, Int<1>{})
    );
    // Weight tensor: (Cout, Cin, K, K)
    auto mW = make_tensor(
        make_gmem_ptr(W),
        make_shape(COUT, CIN, K, K),
        make_stride(CIN * K * K, K * K, K, Int<1>{})
    );
    // Global output tensor for this batch element: (Cout, Hout, Wout)
    const int64_t sYn = (int64_t)COUT * Hout * Wout;
    const int64_t sYc = (int64_t)Hout * Wout;
    auto mY = make_tensor(
        make_gmem_ptr(Y + (int64_t)n * sYn),
        make_shape(COUT, Hout, Wout),
        make_stride(sYc, (int64_t)Wout, Int<1>{})
    );
    // Shared memory tiles
    __shared__ __align__(16) cute::bfloat16_t sX_raw[CIN * SH * SW];
    __shared__ cute::bfloat16_t sW_raw[COUT * CIN * K * K];
    auto sX = make_tensor(
        make_smem_ptr(sX_raw),
        make_shape(CIN, SH, SW),
        make_stride(SH * SW, SW, Int<1>{})
    );
    auto sW = make_tensor(
        make_smem_ptr(sW_raw),
        make_shape(COUT, CIN, K, K),
        make_stride(CIN * K * K, K * K, K, Int<1>{})
    );
    const int tid      = ty * BDIM + tx;
    const int nthreads  = BDIM * BDIM;
    // Cooperative load of weights into shared memory
    const int wtotal = COUT * CIN * K * K;
    for (int i = tid; i < wtotal; i += nthreads) {
        sW_raw[i] = W[i];
    }
    // Cooperative load of input tile into shared memory (vectorized 2-wide loads when safe)
    constexpr int SW2 = SW / 2;
    const bool full_tile = (oh0 + SH <= H) && (ow0 + SW <= Win);
    const bool can_vectorize = full_tile && ((Win & 1) == 0);
    if (can_vectorize) {
        const int xtotal2 = CIN * SH * SW2;
        for (int i = tid; i < xtotal2; i += nthreads) {
            int c    = i / (SH * SW2);
            int rem  = i - c * (SH * SW2);
            int sh   = rem / SW2;
            int sw2i = rem - sh * SW2;
            int sw   = sw2i * 2;
            int ih = oh0 + sh;
            int iw = ow0 + sw;
            const uint32_t* srcp = reinterpret_cast<const uint32_t*>(&mX(c, ih, iw));
            uint32_t packed = *srcp;
            uint32_t* dstp = reinterpret_cast<uint32_t*>(&sX(c, sh, sw));
            *dstp = packed;
        }
    } else {
        const int xtotal = CIN * SH * SW;
        for (int i = tid; i < xtotal; i += nthreads) {
            int c   = i / (SH * SW);
            int rem = i - c * (SH * SW);
            int sh  = rem / SW;
            int sw  = rem - sh * SW;
            int ih = oh0 + sh;
            int iw = ow0 + sw;
            cute::bfloat16_t val = cute::bfloat16_t(0.0f);
            if (ih < H && iw < Win) {
                val = mX(c, ih, iw);
            }
            sX(c, sh, sw) = val;
        }
    }
    __syncthreads();
    constexpr int OC_TILE = 4;
    #pragma unroll 1
    for (int oc0 = 0; oc0 < COUT; oc0 += OC_TILE) {
        float acc[OC_TILE][REG][REG];
        #pragma unroll
        for (int oc_l = 0; oc_l < OC_TILE; ++oc_l) {
            #pragma unroll
            for (int i = 0; i < REG; ++i) {
                #pragma unroll
                for (int j = 0; j < REG; ++j) {
                    acc[oc_l][i][j] = 0.0f;
                }
            }
        }
        #pragma unroll
        for (int ic = 0; ic < CIN; ++ic) {
            #pragma unroll
            for (int kh = 0; kh < K; ++kh) {
                #pragma unroll
                for (int kw = 0; kw < K; ++kw) {
                    float xv[REG][REG];
                    #pragma unroll
                    for (int i = 0; i < REG; ++i) {
                        #pragma unroll
                        for (int j = 0; j < REG; ++j) {
                            xv[i][j] = float(sX(ic, ty * REG + i + kh, tx * REG + j + kw));
                        }
                    }
                    #pragma unroll
                    for (int oc_l = 0; oc_l < OC_TILE; ++oc_l) {
                        float wv = float(sW(oc0 + oc_l, ic, kh, kw));
                        #pragma unroll
                        for (int i = 0; i < REG; ++i) {
                            #pragma unroll
                            for (int j = 0; j < REG; ++j) {
                                acc[oc_l][i][j] += xv[i][j] * wv;
                            }
                        }
                    }
                }
            }
        }
        #pragma unroll
        for (int oc_l = 0; oc_l < OC_TILE; ++oc_l) {
            int oc = oc0 + oc_l;
            #pragma unroll
            for (int i = 0; i < REG; ++i) {
                #pragma unroll
                for (int j = 0; j < REG; ++j) {
                    int oh = oh_base + i;
                    int ow = ow_base + j;
                    if (oh < Hout && ow < Wout) {
                        mY(oc, oh, ow) = cute::bfloat16_t(acc[oc_l][i][j]);
                    }
                }
            }
        }
    }
}

torch::Tensor conv2d_cute_forward(torch::Tensor x, torch::Tensor w) {
    TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
    TORCH_CHECK(x.scalar_type() == at::kBFloat16, "x must be bfloat16");
    TORCH_CHECK(w.scalar_type() == at::kBFloat16, "w must be bfloat16");
    TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
    TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, K, K]");

    int64_t N   = x.size(0);
    int64_t Cin = x.size(1);
    int64_t H   = x.size(2);
    int64_t Win = x.size(3);

    int64_t Cout = w.size(0);
    int64_t Cin_w = w.size(1);
    int64_t K = w.size(2);

    TORCH_CHECK(Cin_w == Cin, "in_channels mismatch between input and weight");
    TORCH_CHECK(w.size(3) == K, "kernel must be square");

    // This kernel is specialized for the given model configuration:
    // in_channels = 3, out_channels = 32, kernel_size = 3, stride=1, padding=0
    TORCH_CHECK(Cin == 3 && Cout == 32 && K == 3,
                "conv2d_cute_forward is specialized for Cin=3, Cout=32, K=3");

    int64_t Hout = H - K + 1;
    int64_t Wout = Win - K + 1;
    TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

    auto x_c = x.contiguous();
    auto w_c = w.contiguous();

    auto y = torch::empty({N, Cout, Hout, Wout}, x.options());

    constexpr int TILE = 32;
    constexpr int CIN  = 3;
    constexpr int COUT = 32;
    constexpr int KK   = 3;
    constexpr int REG  = 2;
    dim3 block(TILE / REG, TILE / REG);
    dim3 grid(
        (unsigned)((Wout + TILE - 1) / TILE),
        (unsigned)((Hout + TILE - 1) / TILE),
        (unsigned)N
    );
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    conv2d_cute_kernel<TILE, CIN, COUT, KK, REG><<<grid, block, 0, stream>>>(
        reinterpret_cast<const cute::bfloat16_t*>(x_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<const cute::bfloat16_t*>(w_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<cute::bfloat16_t*>(y.data_ptr<at::BFloat16>()),
        (int)N, (int)H, (int)Win,
        (int)Hout, (int)Wout
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

conv2d_cute_ext = load_inline(
    name="conv2d_cute_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        in_channels = 3
        out_channels = 32
        kernel_size = 3

        # Match nn.Conv2d default weight initialization (no bias)
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels, kernel_size, kernel_size, dtype=torch.bfloat16)
        )
        self.reset_parameters(in_channels, kernel_size)

        self._ext = conv2d_cute_ext

    def reset_parameters(self, in_channels, kernel_size):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_cute_forward(x.contiguous(), self.weight.contiguous())

